(() => {
 'use strict';
 const D=window.PORTFOLIO, main=document.getElementById('content');
 const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
 const play='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7z"/></svg>';
 const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const shadowAssets=new Set(["sombras-amarillo", "sombras-flores", "sombras-naranja", "sombras-rosa", "sombras-pinceles", "sombras-eli", "sombras-verde", "sombras-hombre"]);
 const legacyImg=(name,alt,extra='')=>`<img src="${name==='cielo-danza'?'assets/cielo-danza-transparente.svg':name==='cielo-danza-documental'?'assets/cielo-danza.webp':name==='caja-rayas'?'assets/caja-rayas-transparente.svg':name==='caja-rayas-documental'?'assets/caja-rayas.webp':name.startsWith('caja-')&&name.endsWith('-frontal')?`assets/${name}-restaurada.png`:shadowAssets.has(name)?`assets/${name}-transparente.png`:name.startsWith('sombras-')&&name.endsWith('-documental')?`assets/${name.replace('-documental','')}.webp`:name==='cielo-globos'?'assets/cielo-globos-transparente.png':name==='cielo-globos-documental'?'assets/cielo-globos.webp':name==='batea'?'assets/batea-transparente.png':name==='batea-documental'?'assets/batea.webp':`assets/${name}.${name.endsWith('-frontal')?'svg':'webp'}`}" alt="${esc(alt)}" ${extra.includes('loading=')?'':'loading="lazy"'} decoding="async" ${extra}>`;
 const img=(name,alt,extra='')=>D.assets?.[name]?`<img src="${D.assets[name]}" alt="${esc(alt)}" ${extra.includes('loading=')?'':'loading="lazy"'} decoding="async" ${extra}>`:legacyImg(name,alt,extra);
 const link=(href,text,cls='text-link')=>`<a class="${cls}" href="${href}">${esc(text)}${arrow}</a>`;
 const external=(href,text)=>`<a class="text-link" href="${href}" target="_blank" rel="noopener noreferrer">${esc(text)}${arrow}<span class="small">(sitio externo)</span></a>`;
 const title=w=>w.title||w.label;
 const series=id=>D.series.find(s=>s.id===id);
 const mail=(subject)=>`mailto:${D.email}?subject=${encodeURIComponent(subject)}`;
 let activeView=0, activeWork=null, filter='Todas';
 function sourceLinks(){return `<aside class="source-links"><p>Documentación del portafolio</p><ul>${D.sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title}</a></li>`).join('')}</ul></aside>`}
 function preview(w){return `<a class="work-preview" href="#/obra/${w.id}"><div class="work-image${w.series==='juego-de-sombras'?' shadows-wall':''}">${img(w.images[0],title(w))}</div><h2>${esc(title(w))}</h2><p class="meta">${esc([w.year,w.dimensions].filter(Boolean).join(' · ')||'Ficha en preparación')}</p><span class="view-work">Ver la obra${arrow}</span></a>`}
 function tabs(id){return `<nav class="series-tabs" aria-label="Series">${D.series.map(s=>`<a href="#/series/${s.id}" ${s.id===id?'aria-current="page"':''}>${s.name}</a>`).join('')}</nav>`}
 function clientsSection(){const clients=D.clients||[];return `<section class="mural-home-feature"><a class="mural-home-photo" href="#/murales" aria-label="Explorar los murales de John Geoffrey Sánchez"><img src="assets/murales/odiseo-registro-01.jpeg" alt="Mural de palmeras de John Geoffrey Sánchez en Odiseo Bistró, con una lámpara de bombillos redondos" loading="lazy" decoding="async"></a><div class="mural-home-copy"><p class="meta">Obras por encargo</p><h2>Paisajes para habitar.</h2><p>La pintura transforma el espacio. Murales de John Geoffrey Sánchez para restaurantes y hoteles, creados en diálogo con la arquitectura y la identidad de cada lugar.</p><p class="small muted">Odiseo Bistró · Kokau, Hotel Hyatt · Tizones</p>${link('#/murales','Explorar los murales','button')}<p class="mural-home-caption small muted">Odiseo Bistró, Cali.</p></div></section>${clients.length?`<section class="clients-section"><div class="clients-heading"><h2>Clientes</h2></div><div class="clients-controls"><button data-clients="prev" aria-label="Ver clientes anteriores">${arrow}</button><button data-clients="next" aria-label="Ver más clientes">${arrow}</button></div><ul class="clients-carousel" aria-label="Clientes">${clients.map(c=>`<li>${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">`:''}<img src="${esc(c.logo)}" alt="${esc(c.name)}" loading="lazy" decoding="async">${c.url?'</a>':''}</li>`).join('')}</ul></section>`:''}`}
 function murals(){const projects=[{"id":"odiseo","name":"Odiseo Bistró","location":"Cali","text":"Un paisaje tropical de palmas y vegetación recorre los muros del restaurante. La pintura dialoga con la altura del espacio, su iluminación y los reflejos del diseño interior.","press":"https://revistaaxxis.com.co/arquitectura/un-tipico-bistro-frances-con-alma-tropical-ubicado-en-cali-colombia/","photos":[{"src":"assets/murales/odiseo-01.jpeg","caption":"Vista del mural en el salón principal"},{"src":"assets/murales/odiseo-02.jpeg","caption":"Otra perspectiva del mural tropical"},{"src":"assets/murales/odiseo-03.jpeg","caption":"Paisajismo en un rincón del restaurante"},{"src":"assets/murales/odiseo-04.jpeg","caption":"Vista completa del mural vertical"},{"src":"assets/murales/odiseo-05.jpeg","caption":"Detalle del mural durante su realización"},{"src":"assets/murales/odiseo-registro-01.jpeg","caption":"El mural y la arquitectura del salón"},{"src":"assets/murales/odiseo-registro-02.jpeg","caption":"Vista del mural durante el proceso"},{"src":"assets/murales/odiseo-registro-03.jpeg","caption":"John Geoffrey junto al mural"}]},{"id":"kokau","name":"Kokau · Hotel Hyatt","location":"Restaurante del hotel Hyatt","text":"Cielos y nubes pintados transforman las paredes del espacio. El proyecto incluye el fondo de nubes del óvalo que enmarca la instalación de globos.","photos":[{"src":"assets/murales/kokau-01.jpeg","caption":"Óvalo con pintura de nubes e instalación de globos"},{"src":"assets/murales/kokau-02.jpeg","caption":"Mural de nubes en el pasillo"},{"src":"assets/murales/kokau-03.jpeg","caption":"Otra vista del cielo pintado"}]},{"id":"tizones","name":"Tizones","location":"Cali","text":"Muros envejecidos, botellas, viñedos y fuego componen una intervención pictórica que acompaña la atmósfera del restaurante. El juego de ilusión integra paisajes y objetos pintados con la arquitectura del lugar.","photos":[{"src":"assets/murales/tizones-01.jpeg","caption":"Muro envejecido con ventana pintada hacia un viñedo"},{"src":"assets/murales/tizones-02.jpeg","caption":"Botellas, barriles y vegetación en el mural"},{"src":"assets/murales/tizones-03.jpeg","caption":"Detalle de botellas, copas y uvas"},{"src":"assets/murales/tizones-04.jpeg","caption":"Vista del mural con fuego en el restaurante"},{"src":"assets/murales/tizones-05.jpeg","caption":"Detalle del fuego y la leña pintados"}]}];return `<div class="page murals-page"><a class="back" href="#/series">${arrow}Todas las obras</a><header class="mural-banner"><img src="assets/murales/odiseo-registro-01.jpeg" alt="Mural de palmeras de John Geoffrey Sánchez en Odiseo Bistró" loading="eager" fetchpriority="high" decoding="async"><div class="mural-banner-shade" aria-hidden="true"></div><div class="mural-banner-copy"><h1>Murales interiores</h1><p>Paisajes para habitar.</p></div></header><div class="murals-intro"><p>John Geoffrey Sánchez desarrolla obras de paisajismo por encargo para restaurantes y hoteles. Esta línea corporativa lleva su pintura al espacio interior y forma parte de su trabajo comisionado en Cali y Cartagena.</p><div><h2>La pintura en el espacio</h2><p class="muted">Paisajismo · Restaurantes y hoteles · Obras por encargo</p>${link(mail('Consulta sobre murales interiores'),'Consultar un encargo','button')}</div></div><ul class="murals-cities" aria-label="Ciudades con obras comisionadas"><li>Cali</li><li>Cartagena</li></ul><nav class="mural-project-nav" aria-label="Proyectos de murales">${projects.map(p=>`<a href="#${p.id}" data-mural-anchor="${p.id}">${esc(p.name)}</a>`).join('')}</nav><div class="mural-projects">${projects.map(p=>`<article class="mural-project" id="${p.id}"><header><p class="meta">${esc(p.location)}</p><h2>${esc(p.name)}</h2><p class="muted">${esc(p.text)}</p>${p.press?external(p.press,'Leer sobre el proyecto en AXXIS'):''}</header><figure class="mural-project-lead"><a href="${p.photos[0].src}" target="_blank" rel="noopener noreferrer" aria-label="Ampliar: ${esc(p.photos[0].caption)}"><img src="${p.photos[0].src}" alt="${esc(p.photos[0].caption)} · ${esc(p.name)}" loading="lazy" decoding="async"></a><figcaption>${esc(p.photos[0].caption)}</figcaption></figure><details class="mural-project-details"><summary>Ver todas las fotografías · ${p.photos.length}</summary><div class="mural-photo-grid">${p.photos.slice(1).map(photo=>`<figure><a href="${photo.src}" target="_blank" rel="noopener noreferrer" aria-label="Ampliar: ${esc(photo.caption)}"><img src="${photo.src}" alt="${esc(photo.caption)} · ${esc(p.name)}" loading="lazy" decoding="async"></a><figcaption>${esc(photo.caption)}</figcaption></figure>`).join('')}</div></details></article>`).join('')}</div></div>`}
 function classContact(city){const subject=city==='Cali'?'Clases personalizadas a domicilio en Cali':'Preagenda de clase personalizada en Bogotá';const body=city==='Cali'?'Hola John Geoffrey, me gustaría conocer tus clases personalizadas a domicilio en Cali.\n\nDisciplina de interés (dibujo, anatomía o pintura):\nMi experiencia o formación: \nZona de Cali: \nDisponibilidad: ':'Hola John Geoffrey, me gustaría preagendar una clase personalizada durante uno de tus próximos viajes a Bogotá.\n\nDisciplina de interés (dibujo, anatomía o pintura):\nMi experiencia o formación: \nFechas o disponibilidad: \nMe gustaría consultar la reserva y las opciones de prepago.';return `mailto:${D.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
 function teachingSection(){return `<section class="teaching-section"><h2>Compartir el<br>proceso creativo.</h2><div><p>John Geoffrey disfruta acompañar la búsqueda creativa y el aprendizaje de la técnica, especialmente de artistas en formación.</p><p class="muted">Clases personalizadas de dibujo, anatomía y pintura a domicilio en Cali. Encuentros en Bogotá durante sus viajes anunciados.</p>${link('#/servicios','Conocer las clases y talleres')}</div></section>`}
 function services(){const visits=D.bogotaVisits||[];return `<div class="page services-page"><header class="page-heading"><h1>Servicios</h1><p class="muted">Acompañamiento artístico y pintura por encargo.</p></header><section class="teaching-intro"><h2>Clases y acompañamiento artístico</h2><p>John Geoffrey disfruta acompañar el proceso creativo y el aprendizaje de la técnica, especialmente de artistas en formación. Sus clases personalizadas de dibujo, anatomía y pintura ofrecen un espacio para desarrollar la mirada, explorar el lenguaje propio y trabajar la práctica artística.</p><ul class="teaching-disciplines" aria-label="Disciplinas de las clases"><li>Dibujo</li><li>Anatomía</li><li>Pintura</li></ul></section><section class="teaching-location"><h2>Clases a domicilio en Cali</h2><div><p>Cali es su ciudad de residencia principal. Allí ofrece clases a domicilio y acompañamiento personalizado para quienes desean avanzar en su formación artística.</p>${link(classContact('Cali'),'Consultar clases en Cali','button')}</div></section><section class="teaching-location"><h2>Encuentros en Bogotá</h2><div><p>Durante sus viajes a Bogotá también será posible tomar clases con él. Las próximas visitas y fechas disponibles se anunciarán en este espacio.</p>${visits.length?`<ul class="teaching-visits">${visits.map(v=>`<li><strong>${esc(v.date)}</strong>${v.note?`<p class="muted">${esc(v.note)}</p>`:''}</li>`).join('')}</ul>`:'<p class="muted">Próximas fechas por anunciar.</p>'}<p>Puedes dejar tu interés preagendado y coordinar una reserva anticipada, incluido el prepago, directamente con el artista. La fecha, el valor y la reserva se acuerdan con él.</p>${link(classContact('Bogotá'),'Preagendar una clase en Bogotá','button')}</div></section><section class="teaching-location"><h2>Obras por encargo o comisionadas</h2><div><p>John Geoffrey Sánchez desarrolla obras por encargo para tu negocio u hogar. Con la asesoría del artista, la propuesta se define en diálogo con el espacio y con lo que buscas.</p>${link(mail('Consulta sobre una obra por encargo'),'Consultar una obra por encargo','button')}</div></section></div>`}
 function home(){return `<section class="hero"><div class="hero-copy"><h1><span>Habitar</span> <span>el vacío.</span></h1><p class="muted">Pintura, materia y percepción.</p>${link('#/series','Explorar la obra','button')}</div><a class="hero-art" href="#/series/eco-de-luz" aria-label="Entrar en la serie Eco de luz"><img src="assets/caja-rayas-transparente.svg" alt="Caja de John Geoffrey Sánchez: una figura ante planos curvos con franjas turquesa y negras" fetchpriority="high" decoding="async"></a></section>
 <section class="home-series"><h2>Una mirada<br>a sus series</h2><nav aria-label="Series principales"><a href="#/series/eco-de-luz">Eco de luz</a><a href="#/series/a-cielo-abierto">A cielo abierto</a><a href="#/series/ser-y-parecer">Ser y parecer</a>${link('#/series','Ver más series','button home-series-more')}</nav><a class="sphere-object" href="#/obra/aleacion-2024" aria-label="Ver Aleación 3, 2024"><img src="assets/aleacion-home-cutout.png" alt="Esfera de Aleación, 2024, integrada sobre el fondo oscuro" class="home-sphere" width="1254" height="1254" decoding="async"></a></section>
 <section class="intro"><h2>La pintura continúa más allá de su superficie.</h2><div><p>John Geoffrey Sánchez trabaja con la figura humana, la ilusión y los vacíos que construye para sus imágenes. Cajas, bateas y esferas amplían la relación entre pintura, materia y mirada.</p>${link('#/artista','Conocer al artista')}</div></section>
 <section class="feature">${img('cajas-exposicion','Cuatro cajas expuestas en Borboleta Gallery en septiembre de 2026')}<div><h2>Entre raíces y memoria: lo que permanece</h2><p class="meta">Borboleta Gallery · Septiembre de 2026</p><p>Un encuentro con su obra reciente: figuras que esperan, leen y se detienen dentro de planos de color.</p>${link('#/series/eco-de-luz','Recorrer Eco de luz')}</div></section>${clientsSection()}${teachingSection()}`}
 function seriesIndex(){return `<div class="page"><header class="page-heading"><h1>Obras</h1><p class="muted">Distintos soportes. Una exploración de la figura, la materia y aquello que creemos ver.</p></header><div class="series-list">${D.series.map(s=>`<article class="series-feature ${s.wall?'series-wall':''}"><a class="series-cover" href="#/series/${s.id}" aria-label="Explorar ${s.name}">${s.wall?'<img src="assets/ser-parecer-pared-extendida.png" alt="Ser y parecer en una pared de galería, con el entorno extendido" loading="lazy" decoding="async">':img(s.image,s.name)}</a><div><h2>${s.name}</h2><p>${s.text}</p>${link('#/series/'+s.id,'Explorar la serie')}</div></article>`).join('')}</div><section class="murals-index murals-index-photo"><a class="murals-index-image" href="#/murales" aria-label="Explorar los murales interiores"><img src="assets/murales/kokau-01.jpeg" alt="Mural de nubes e instalación de globos en Kokau, hotel Hyatt" loading="lazy" decoding="async"></a><div><h2>Murales interiores</h2><p class="muted">Paisajismo por encargo para restaurantes y hoteles en Cali y Cartagena.</p></div><div>${link('#/murales','Conocer esta línea de trabajo')}</div></section><aside class="archive"><h2>Obras tempranas</h2><p class="muted">El archivo inicial reúne otras exploraciones pictóricas, con paisajes, animales y escenas de la vida cotidiana. Puede consultarse en el portafolio de Artelista.</p>${external('https://www.artelista.com/@johngeoffrey','Consultar el archivo')}</aside></div>`}
 function seriesIntro(s){const back=`<a class="back" href="#/series">${arrow}Todas las series</a>`;if(s.id!=='a-cielo-abierto')return `${back}<header class="series-heading"><h1>${s.name}</h1><p class="muted">${s.text}</p></header>`;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const heroAsset='a-cielo-abierto';return `<header class="series-video-hero"><video id="series-hero-video" ${reduced?'':'autoplay'} muted loop playsinline preload="metadata" poster="assets/${heroAsset}-hero-poster.jpg" aria-hidden="true"><source src="assets/${heroAsset}-hero.mp4" type="video/mp4"></video><div class="series-video-overlay"></div><div class="series-video-copy">${back}<p class="series-video-eyebrow">El territorio y la mirada</p><h1>${esc(s.name)}</h1><p class="series-video-description">${esc(s.text)}</p></div><button class="series-video-toggle" data-video-toggle aria-controls="series-hero-video">${reduced?'Reproducir video':'Pausar video'}</button></header>`}
 function seriesPage(id){const s=series(id);if(!s)return notFound();const works=D.works.filter(w=>w.series===id),normal=works.filter(w=>!w.group),grouped=works.filter(w=>w.group);const groups=[...new Set(grouped.map(w=>w.group))].map(name=>{const g=s.groups?.find(g=>g.name===name);return `<section id="${esc(g?.id||name)}"><header class="sub-series"><h2>${esc(g?.heading||name)}</h2><p class="muted">${esc(g?.text||'La ilusión pictórica sobre una esfera: fracturas, materia y reflejos que incorporan el entorno.')}</p></header><div class="works-grid">${grouped.filter(w=>w.group===name).map(preview).join('')}</div></section>`}).join('');const first=id==='a-cielo-abierto';return `<div class="page${id==='a-cielo-abierto'?' series-video-page':''}">${seriesIntro(s)}${tabs(id)}${s.artistStatement?`<section class="artist-statement" aria-labelledby="statement-title"><p class="artist-eyebrow">Texto del artista</p><h2 id="statement-title">Ser y parecer</h2><p class="statement-lead">${esc(s.artistStatement[0])}</p><details><summary>Leer el texto completo</summary><div class="statement-body">${s.artistStatement.slice(1).map(p=>`<p>${esc(p)}</p>`).join('')}</div></details><p class="statement-author">John Geoffrey Sánchez</p></section>`:''}${first?groups:''}<div class="works-grid${first?' works-after-mining':''}">${normal.map(preview).join('')}</div>${first?'':groups}${s.note?`<p class="note">${s.note}</p>`:''}<p class="note">Los rótulos descriptivos identifican las fotografías cuando el título de la obra aún no está confirmado.</p></div>`}
 function detail(id){const w=D.works.find(w=>w.id===id);if(!w)return notFound();activeWork=w;activeView=0;const s=series(w.series);const same=D.works.filter(x=>x.series===w.series),pos=same.indexOf(w);return `<div class="page"><a class="back" href="#/series/${s.id}">${arrow}${s.name}</a><article class="work-detail"><div><div class="detail-image${w.series==='juego-de-sombras'?' shadows-wall':''}">${img(w.images[0],title(w),'id="current-image" loading="eager"')}</div>${w.images.length>1?`<div class="view-controls"><button data-view="prev" aria-label="Vista anterior" disabled>${arrow}</button><p id="view-status" aria-live="polite">Vista 1 de ${w.images.length}</p><button data-view="next" aria-label="Vista siguiente">${arrow}</button></div><div class="thumbnails" aria-label="Vistas de la obra">${w.images.map((image,i)=>`<button class="thumbnail" data-index="${i}" aria-label="Ver vista ${i+1}" aria-pressed="${i===0}">${img(image,'Vista '+(i+1))}</button>`).join('')}</div>`:''}</div><div class="detail-info"><p class="series-ref">${s.name}${w.group?' / '+w.group:''}</p><h1>${esc(title(w))}</h1>${!w.title?'<p class="small muted">Rótulo descriptivo · título por confirmar</p>':''}<dl class="facts"><dt>Artista</dt><dd>John Geoffrey Sánchez</dd><dt>Año</dt><dd>${esc(w.year||'Por confirmar')}</dd><dt>Técnica</dt><dd>${esc(w.medium||'Por confirmar')}</dd><dt>Medidas</dt><dd>${esc(w.dimensions||'Por confirmar')}</dd>${w.exhibition?`<dt>Presentación</dt><dd>${esc(w.exhibition)}</dd>`:''}</dl>${w.description?`<p class="muted">${esc(w.description)}</p>`:''}${link(mail('Consulta sobre la obra: '+title(w)),'Consultar esta obra','button')}<p class="note">Disponibilidad e información adicional directamente con el artista.</p></div></article><nav class="work-pagination" aria-label="Otras obras de esta serie">${pos>0?link('#/obra/'+same[pos-1].id,'Obra anterior'):link('#/series/'+s.id,'Volver a la serie')}${pos<same.length-1?link('#/obra/'+same[pos+1].id,'Siguiente obra'):link('#/series/'+s.id,'Volver a la serie')}</nav></div>`}
 function artist(){return `<div class="artist-editorial"><header class="artist-studio-hero"><img class="artist-studio-wide" src="assets/artista-estudio-16x9.png" alt="John Geoffrey Sánchez pintando en su estudio, junto a su caballete y materiales" loading="eager" fetchpriority="high" decoding="async" width="1672" height="941"><div class="artist-studio-shade" aria-hidden="true"></div><div class="artist-hero-copy"><p class="artist-eyebrow">El artista · En su estudio</p><h1>John Geoffrey<br>Sánchez</h1><p>La figura, la materia y el vacío.<br>Una práctica que invita a mirar de nuevo.</p>${link('#/series','Explorar la obra','button')}</div></header><div class="artist-content"><section class="artist-geography" aria-label="Origen, formación y estudio"><div><span>Origen</span><strong>Cumbitara</strong><p>Nariño, Colombia</p></div><div><span>Formación</span><strong>Bogotá</strong><p>ASAB · Artes Plásticas y Visuales</p></div><div><span>Estudio</span><strong>Cali</strong><p>Su residencia principal</p></div></section><section class="artist-profile"><div class="artist-profile-copy"><h2>La mirada se forma.<br>La búsqueda continúa.</h2><div class="bio">${D.artistBiography.map(p=>`<p>${esc(p)}</p>`).join('')}</div></div><figure class="artist-profile-portrait"><img src="assets/artista-estudio-retrato.jpeg" alt="John Geoffrey Sánchez en su estudio, rodeado de pinturas y materiales" loading="lazy" decoding="async" width="1755" height="2048"><figcaption>John Geoffrey Sánchez · En su estudio</figcaption></figure></section><section class="artist-studio-document"><figure><img src="assets/artista-pintando-original.jpeg" alt="John Geoffrey Sánchez trabajando en una pintura junto a la ventana de su estudio" loading="lazy" decoding="async" width="1080" height="1080"><figcaption>El artista trabajando en su estudio</figcaption></figure><div><p class="artist-eyebrow">En palabras del artista</p><h2>La superficie.<br>Un universo interior.</h2><blockquote>${esc(D.series.find(s=>s.id==='ser-y-parecer').artistStatement[0])}</blockquote>${link('#/series/ser-y-parecer','Leer el texto de Ser y parecer')}</div></section><section class="artist-practice"><h2>La imagen y el vacío.</h2><div class="artist-practice-intro"><p>Su trabajo reúne pintura, objeto y arquitectura. Bateas, cajas y esferas permiten que la imagen dialogue con la profundidad, la luz y el entorno. La mirada del visitante forma parte de esa relación.</p><p>En sus escenas aparecen personas del común, a menudo de espaldas, concentradas en un gesto o detenidas en contemplación. Sus figuras no explican todo lo que les ocurre: dejan abierta la experiencia de quien observa.</p></div><ol class="artist-process" aria-label="Relaciones en su práctica artística"><li><img src="assets/artist-icons/eye.svg" alt="" aria-hidden="true"><h3>La mirada</h3><p>Figuras del común, gestos y momentos de contemplación. La imagen deja abierta la experiencia de quien observa.</p></li><li><img src="assets/artist-icons/brush.svg" alt="" aria-hidden="true"><h3>La pintura</h3><p>La precisión pictórica construye apariencias y hace que las superficies parezcan abrirse, fracturarse o transformarse.</p></li><li><img src="assets/artist-icons/cube.svg" alt="" aria-hidden="true"><h3>El espacio</h3><p>Cajas, bateas y esferas ponen la pintura en relación con la profundidad, la luz y la posición del visitante.</p></li></ol><div class="artist-series-path"><span>Distintas formas de mirar</span>${D.series.filter(x=>['eco-de-luz','a-cielo-abierto','ser-y-parecer'].includes(x.id)).map(x=>`<a href="#/series/${x.id}">${esc(x.name)}${arrow}</a>`).join('')}</div></section><section class="artist-circulation"><h2>Un recorrido compartido.</h2><div><p>Su obra ha circulado en exposiciones y ferias de arte en Colombia y en ciudades como Lima, Nueva York y Miami. La documentación de su trayectoria incluye su relación con Galería Casa Cuadrada, Soyarte y Borboleta Gallery.</p>${link('#/trayectoria','Ver trayectoria y participaciones')}</div></section><section class="recognition"><div><h2>Formación</h2><p class="muted">ASAB · Universidad Distrital Francisco José de Caldas<br>Artes Plásticas y Visuales · 2005–2011</p></div><div><h2>Reconocimientos</h2><ul><li>Tesis meritoria por el proyecto <em>Ser y parecer</em>.</li><li>Beca Proyecto Tesis · Museo de Arte Contemporáneo de Bogotá · 2009.</li><li>Segundo puesto · V Salón Nacional de Pintura de Nariño.</li><li>Mención de honor · XI Salón Diversidad · Galería Casa Cuadrada.</li></ul><p class="note">Según la trayectoria publicada por Galería Casa Cuadrada. Las fechas no consignadas se completarán con el artista.</p></div></section>${sourceLinks()}</div></div>`}
 function eventRows(){const entries=D.events.filter(e=>filter==='Todas'||e.type===filter);return entries.map(e=>`<article class="event-row"><div class="event-year">${e.year}</div><div><h3>${e.title}</h3><p>${e.date}</p></div><p class="event-place">${e.place}</p><p class="event-type">${e.type}</p>${e.image?`<details><summary>Ver registro de participación</summary>${img(e.image,e.title+' · documento o fotografía de participación')}</details>`:''}</article>`).join('')}
 function trajectory(){filter='Todas';return `<div class="page"><header class="page-heading"><h1>Trayectoria</h1><p class="muted">Exposiciones, ferias de arte y galerías. Su recorrido en Colombia y en el exterior, desde 2006.</p></header><h2>Galerías representantes</h2><div class="gallery-list"><article><div class="gallery-logo gallery-logo-casa-cuadrada"><img src="assets/logo-casa-cuadrada-transparente.png" alt="Logo de Casa Cuadrada" loading="lazy" decoding="async"></div><h2>Casa Cuadrada</h2><p>Bogotá · Colombia</p></article><article><div class="gallery-logo gallery-logo-soyarte"><img src="assets/logo-soyarte-transparente.png" alt="Logo de Soyarte" loading="lazy" decoding="async"></div><h2>Soyarte</h2><p>Galería representante</p></article><article><div class="gallery-logo gallery-logo-borboleta"><img src="assets/logo-borboleta-transparente.png" alt="Logo de Borboleta Gallery" loading="lazy" decoding="async"></div><h2>Borboleta Gallery</h2><p>Galería representante · exposición de septiembre de 2026</p></article></div><h2>Exposiciones y ferias</h2><div class="filters" aria-label="Filtrar participaciones">${['Todas','Exposición','Feria'].map(f=>`<button data-filter="${f}" aria-pressed="${f==='Todas'}">${f==='Exposición'?'Exposiciones':f==='Feria'?'Ferias':f}</button>`).join('')}</div><p id="event-count" class="small muted" aria-live="polite">${D.events.length} participaciones</p><div id="event-list">${eventRows()}</div><p class="note">Trayectoria actualizada según el portafolio 2026 del artista, complementada con los registros de participación aportados.</p>${sourceLinks()}</div>`}
 function press(){const articles=[{date:'2022-02-14',html:`<article class="press-item"><figure class="press-photo"><img class="press-axxis-image" src="assets/prensa-axxis-noticia.svg" alt="Noticia de Revista AXXIS sobre Odiseo Bistró, con titular, fecha y fotografía del mural" loading="lazy" decoding="async"><figcaption>Fotografía Andre Nazareth - Revista Axxis</figcaption></figure><h2>Un típico bistró francés con alma tropical ubicado en Cali, Colombia</h2><p class="meta">Revista AXXIS · Arquitectura · 14 de febrero de 2022</p><p>Un recorrido por Odiseo Bistró, en Cali, y su diseño interior a cargo de Camilo Sighinolfi. El artículo destaca el mural que John Geoffrey Sánchez pintó en el lugar y su presencia en los reflejos que recorren el restaurante.</p>${external('https://revistaaxxis.com.co/arquitectura/un-tipico-bistro-frances-con-alma-tropical-ubicado-en-cali-colombia/','Leer en AXXIS')}</article>`},{date:'2017-08-04',html:`<article class="press-item"><figure class="press-photo"><img class="press-axxis-image" src="assets/prensa-exclama-sin-borde.svg" alt="Visitantes frente a la obra de John Geoffrey Sánchez en el Click Clack Hotel" loading="lazy" decoding="async"><figcaption>Fotografía del artículo «Plástica y placer en el Click Clack Hotel» · Revista EXCLAMA</figcaption></figure><h2>Plástica y placer en el Click Clack Hotel</h2><p class="meta">EXCLAMA · Arte y eventos · 4 de agosto de 2017</p><p>Una crónica de la segunda edición de «Esto no es una galería» en el Click Clack Hotel. EXCLAMA registra la participación de John Geoffrey junto a artistas colombianos e internacionales en una exposición que propicia el encuentro del público con las obras fuera de los espacios convencionales.</p>${external('https://revistaexclama.com/plastica-y-placer-en-el-click-clack-hotel/','Leer en EXCLAMA')}</article>`},{date:'2016-05-19',html:`<article class="press-lead"><a class="video-cover" href="https://www.youtube.com/watch?v=B9TNJxt7-hs" target="_blank" rel="noopener noreferrer" aria-label="Ver entrevista a John Geoffrey Sánchez en Panorama CMI en YouTube"><img src="https://i.ytimg.com/vi/B9TNJxt7-hs/hqdefault.jpg" alt="Entrevista de Panorama CMI a John Geoffrey Sánchez" loading="lazy"><span class="play">${play}Ver en YouTube · 2:29</span></a><div><h2>Pintura, percepción y proceso creativo</h2><p class="meta">Entrevista · Panorama CMI · 19 de mayo de 2016</p><p>El artista habla de su infancia en Nariño, del trabajo contemplativo en el taller y de la relación entre pintura y arquitectura en Ser y parecer.</p><p class="small muted">Título original del video: «Personaje Panorama John Geoffrey Sánchez Artista Plástico».</p>${external('https://www.youtube.com/watch?v=B9TNJxt7-hs','Ver la entrevista')}</div></article>`},{date:'2015-02-28',html:`<article class="press-item"><h2>Perfil y trayectoria internacional</h2><p class="meta">El Tiempo · 28 de febrero de 2015</p><p>Un perfil periodístico que recorre sus orígenes en Nariño, su formación y la circulación internacional de su obra.</p>${external('https://www.eltiempo.com/archivo/documento/cms-15315696','Leer en El Tiempo')}<p class="small muted">La entrada utiliza un descriptor editorial; el titular original se conserva en el medio de publicación.</p></article>`},{date:null,html:`<article class="press-item"><h2>Una conversación sobre Ser y parecer</h2><p class="meta">Más arte más ciudad · Texto de John Gómez · Fecha por confirmar</p><p>Una lectura sobre la precisión pictórica, las apariencias y las preguntas que surgen al detenerse ante la obra.</p>${external('https://www.instagram.com/reel/DaS-Luwp2JK/','Ver la conversación')}<details><summary>Leer una síntesis del texto de John Gómez</summary><div class="essay"><p>En su lectura de Ser y parecer, John Gómez observa cómo la ilusión visual conduce a una mirada más lenta. La semejanza con lo real atrae al espectador y abre la posibilidad de cuestionar sus primeras impresiones.</p><p>Esta síntesis parafrasea el texto de John Gómez aportado como referencia; no es una declaración del artista.</p></div></details>${img('prensa-cmi','Encuentro de John Geoffrey Sánchez y John Gómez junto a tres esferas de Aleación')}</article>`},{date:null,html:`<article class="press-item"><h2>Un artista nariñense en el circuito del arte</h2><p class="meta">Recorte de prensa aportado al archivo</p><p>Un registro de su formación y de sus participaciones con Galería Casa Cuadrada.</p><details><summary>Ver recorte de prensa</summary>${img('prensa-narino','Recorte de prensa sobre John Geoffrey Sánchez')}</details><p class="note">Medio, autor y fecha por confirmar.</p></article>`}];return `<div class="page"><header class="page-heading"><h1>Prensa y conversaciones</h1><p class="muted">Otras voces y encuentros alrededor de la obra.</p></header><div class="press-items">${articles.filter(a=>a.date).sort((a,b)=>b.date.localeCompare(a.date)).map(a=>a.html).join('')}</div><section class="press-undated"><h2>Otros registros</h2><p class="muted">Publicaciones con fecha por confirmar.</p><div class="press-items">${articles.filter(a=>!a.date).map(a=>a.html).join('')}</div></section></div>`}
 function contact(){return `<div class="page contact"><h1>Conversemos<br>sobre la obra.</h1><p class="muted">Para consultas sobre obras, clases personalizadas, talleres, murales, exposiciones y colaboraciones.</p><a class="email" href="mailto:${D.email}">${D.email}${arrow}</a><div class="contact-secondary"><a href="https://www.instagram.com/jgeoffreyart/" target="_blank" rel="noopener noreferrer">Instagram · @jgeoffreyart</a><a href="#/servicios">Clases y talleres</a><a href="#/trayectoria">Galerías representantes</a></div><p class="note">El enlace de correo abre tu aplicación de email.</p></div>`}
 function notFound(){return `<div class="page empty"><h1>No encontramos esta página.</h1><p>Continúa el recorrido por las series del artista.</p>${link('#/series','Ver las series','button')}</div>`}
 function closeMenu(){const btn=document.querySelector('.menu-toggle');btn.setAttribute('aria-expanded','false');document.getElementById('navigation').classList.remove('open')}
 function render(){const parts=(location.hash.slice(1)||'/').split('/').filter(Boolean),route=parts[0]||'inicio',id=parts[1]==='cajas'?'eco-de-luz':parts[1]==='mineria-legal'?'a-cielo-abierto':parts[1];activeWork=null;const w=route==='obra'?D.works.find(w=>w.id===id):null;const wall=route==='series'&&id==='ser-y-parecer'||w?.series==='ser-y-parecer';document.body.classList.toggle('wall-room',Boolean(wall));document.querySelector('meta[name="theme-color"]').content=wall?'#f3f3f2':'#111010';closeMenu();main.classList.remove('page-enter');main.innerHTML=route==='inicio'?home():route==='artista'?artist():route==='murales'?murals():route==='servicios'?services():route==='series'?(id?seriesPage(id):seriesIndex()):route==='obra'?detail(id):route==='trayectoria'?trajectory():route==='prensa'?press():route==='contacto'?contact():notFound();document.title=`${route==='inicio'?'Pintura, materia y percepción':w?title(w):id&&series(id)?series(id).name:({artista:'El artista',murales:'Murales interiores',servicios:'Servicios',series:'Obras',trayectoria:'Trayectoria',prensa:'Prensa',contacto:'Contacto'}[route]||'Página no encontrada')} — John Geoffrey Sánchez`;document.querySelectorAll('#navigation a').forEach(a=>{const isActive=a.hash===`#/${route}`||(a.hash==='#/series'&&['obra','murales'].includes(route));if(isActive)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>main.classList.add('page-enter'));main.focus({preventScroll:true});const heroVideo=document.getElementById('series-hero-video');if(heroVideo){const toggle=main.querySelector('[data-video-toggle]');const sync=()=>{toggle.textContent=heroVideo.paused?'Reproducir video':'Pausar video'};heroVideo.addEventListener('play',sync);heroVideo.addEventListener('pause',sync);sync();}if(parts[1]==='mineria-legal')document.getElementById('mineria-legal')?.scrollIntoView();const hero=document.querySelector('.hero-art');if(hero&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&matchMedia('(pointer:fine)').matches){hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();hero.style.setProperty('--rotate',((e.clientX-r.left)/r.width-.5)*3+'deg')});hero.addEventListener('pointerleave',()=>hero.style.setProperty('--rotate','0deg'))}main.querySelectorAll('img').forEach(im=>im.addEventListener('error',()=>{if(im.src.includes('ytimg')){im.src='assets/prensa-cmi.webp';im.alt='Registro de una conversación con John Geoffrey Sánchez'}else {const notice=document.createElement('p');notice.className='note';notice.textContent='No se pudo cargar esta fotografía. Recarga la página para volver a intentarlo.';im.replaceWith(notice)}},{once:true}))}
 function changeView(index){if(!activeWork)return;activeView=Math.max(0,Math.min(index,activeWork.images.length-1));document.querySelector('.detail-image').innerHTML=img(activeWork.images[activeView],`${title(activeWork)} · vista ${activeView+1}`,'id="current-image" loading="eager"');document.getElementById('view-status').textContent=`Vista ${activeView+1} de ${activeWork.images.length}`;document.querySelector('[data-view="prev"]').disabled=activeView===0;document.querySelector('[data-view="next"]').disabled=activeView===activeWork.images.length-1;document.querySelectorAll('[data-index]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.index)===activeView))}
 document.querySelector('.menu-toggle').addEventListener('click',()=>{const btn=document.querySelector('.menu-toggle'),open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',open);document.getElementById('navigation').classList.toggle('open',open)});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();document.querySelector('.menu-toggle').focus()}if(e.target.closest('.view-controls,.thumbnails')){if(e.key==='ArrowRight')changeView(activeView+1);if(e.key==='ArrowLeft')changeView(activeView-1)}});
 main.addEventListener('click',e=>{const anchor=e.target.closest('[data-mural-anchor]');if(anchor){e.preventDefault();document.getElementById(anchor.dataset.muralAnchor)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
 main.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.hasAttribute('data-video-toggle')){const video=document.getElementById('series-hero-video');if(video.paused)video.play().catch(()=>{btn.textContent='Reproducir video'});else video.pause();}if(btn.dataset.clients){const track=document.querySelector('.clients-carousel');track?.scrollBy({left:(btn.dataset.clients==='next'?1:-1)*track.clientWidth*.8,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}if(btn.dataset.view)changeView(activeView+(btn.dataset.view==='next'?1:-1));if(btn.dataset.index!==undefined)changeView(Number(btn.dataset.index));if(btn.dataset.filter){filter=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===filter));document.getElementById('event-list').innerHTML=eventRows();document.getElementById('event-count').textContent=`${D.events.filter(e=>filter==='Todas'||e.type===filter).length} participaciones`}});
 window.addEventListener('hashchange',render);render();
})();
